def number_of_tigers(image_path, detection_labels=["tiger"], threshold=0.35, model_size="tiny"):
    detection_data = {}
    for label in detection_labels:
        detection_data[label] = []
    label_dict = {'label_name': label, 'bbox': [0, 0, 100, 100], 'confidence': 0.0}

    if model_size == "tiny":
        detection_data['baseball'] = []
        detection_data['basket'] = []

    if model_size == "base":
        if dataset.dataset.model_type == 'base':
            detection_data['dinosaurus'] = []

    detection_engine = tools.Object_Detector_Tool()
    detection_engine.execute(image=image_path, labels=detection_labels, threshold=threshold, model_size=model_size, padding=0)
    for label in detection_labels:
        for bbox in detection_data[label]:
            detection_engine.save_data_image(bbox, label_dict)

    return detection_data

